/// Filters an env-var snapshot down to registry-credential values this
/// codebase's publish flow reads: the names in [`SECRET_CREDENTIAL_ENV`], plus any
/// `CARGO_REGISTRIES_<NAME>_TOKEN` (operator-configured, unbounded name,
/// so matched by pattern). `GITHUB_TOKEN`/`GH_TOKEN` cover GitHub Actions'
/// ambient credential -- `redact_url_userinfo` already catches its most
/// realistic leak shape (an authenticated remote URL) independently, but
/// matching the env var names directly is cheap insurance against other
/// leak shapes.
///
/// Takes the snapshot as a parameter (callers pass `std::env::vars()`)
/// rather than reading the environment directly -- deterministic, no
/// process-env mutation in tests.
pub fn known_credential_env_values(vars: impl Iterator<Item = (String, String)>) -> Vec<String> {
    vars.filter(|(key, value)| {
        !value.is_empty()
            && (SECRET_CREDENTIAL_ENV.contains(&key.as_str())
                || (key.starts_with("CARGO_REGISTRIES_") && key.ends_with("_TOKEN"))
                || (value.len() >= MIN_SECRET_VALUE_LEN && SECRET_NAME_SUFFIXES.iter().any(|s| key.ends_with(s))))
    })
    .map(|(_, value)| value)
    .collect()
}

/// Any variable named like a secret has its value redacted too, unless the value is so short that masking it would
/// mangle ordinary text.
const SECRET_NAME_SUFFIXES: &[&str] = &["_TOKEN", "_SECRET", "_PASSWORD"];
const MIN_SECRET_VALUE_LEN: usize = 8;

/// The environment variables whose values are secrets. A username and the paths of generated config files
/// (`TWINE_USERNAME`, `NPM_CONFIG_USERCONFIG`, `CALLISTO_PUBLISH_NPM_CONFIG`) are credentials to keep out of
/// unrelated children but are not secret values, so they are not listed.
pub const SECRET_CREDENTIAL_ENV: &[&str] = &[
    "ACTIONS_ID_TOKEN_REQUEST_TOKEN",
    "NPM_TOKEN",
    "NPM_CONFIG_TOKEN",
    "NODE_AUTH_TOKEN",
    "PYPI_TOKEN",
    "TWINE_PASSWORD",
    "CARGO_REGISTRY_TOKEN",
    "GITHUB_TOKEN",
    "GH_TOKEN",
];

/// The one definition of "how this workspace redacts a subprocess's stderr":
/// [`redact_known_secrets`] over [`known_credential_env_values`] of the live
/// environment. Every path that puts child stderr in front of a human -- the
/// live echo, [`crate::CommandOutput::redacted_stderr`], and the
/// `CommandFailure::NonZeroExit` diagnostic -- composes it here rather than
/// repeating the composition, so none of them can drift out of step.
///
/// Reads the environment, so it is deliberately not the pure primitive;
/// unit tests target [`redact_known_secrets`] with an explicit secret list.
pub fn redact_command_stderr(stderr: &str) -> String {
    redact_known_secrets(stderr, &known_credential_env_values(std::env::vars()))
}

