11	pub fn package_paths(pkg: &Package) -> Vec<PathBuf> {
12	    let mut set = std::collections::BTreeSet::new();
13	    for m in &pkg.manifests {
14	        if let Some(parent) = m.path.parent() {
15	            if parent.as_os_str().is_empty() {
16	                set.insert(PathBuf::from("."));
17	            } else {
18	                set.insert(parent.to_path_buf());
19	            }
20	        }
21	    }
22	    set.into_iter().collect()
23	}
