96	/// Paths whose edits do not change what ships: tests, benches, examples, snapshots and Markdown.
97	pub const DEFAULT_IGNORED_PATHS: &[&str] = &["tests/", "benches/", "examples/", "*.snap", "*.md", "CHANGELOG.md"];
98	
99	/// Files under each package's directories that differ between its last tag and `HEAD` or the working tree, minus the
100	/// `ignore` pathspecs (a trailing `/` names a directory at any depth, anything else a file glob). An untagged package, or
101	/// one whose tag is not a commit, yields all its tracked files. One git invocation per distinct tag commit, plus one per
102	/// untagged package.
103	pub fn changed_source_files_since_last_tag(
104	    packages: &[&Package],
105	    tags: &TagIndex,
106	    git: &GitAccess<'_>,
107	    ignore: &[&str],
108	) -> Result<BTreeMap<PackageId, Vec<PathBuf>>, GraphError> {
109	    changed_source_files_in_batches(packages, tags, git, ignore, PATHSPEC_BUDGET)
110	}
111	
112	/// The most pathspec bytes one `git diff` gets, so a very large workspace stays under a command-line length limit
113	/// (32 KB on Windows) by splitting into a few diffs instead of one.
114	const PATHSPEC_BUDGET: usize = 24_000;
115	
116	fn changed_source_files_in_batches(
117	    packages: &[&Package],
118	    tags: &TagIndex,
119	    git: &GitAccess<'_>,
120	    ignore: &[&str],
121	    budget: usize,
122	) -> Result<BTreeMap<PackageId, Vec<PathBuf>>, GraphError> {
123	    let excludes: Vec<String> = ignore.iter().map(|pattern| exclude_pathspec(pattern)).collect();
124	    let mut result = BTreeMap::new();
125	    let mut by_base: BTreeMap<String, Vec<(&Package, Vec<PathBuf>)>> = BTreeMap::new();
126	    for pkg in packages {
127	        let base = match tags.last_tag(&pkg.id) {
128	            Some(last) => tags.commit_of(git, last.name.as_str())?,
129	            None => None,
130	        };
131	        let directories = package_paths(pkg);
132	        match base {
133	            // With no directory the pathspec would be empty and match everything, so it is not batched.
134	            Some(commit) if !directories.is_empty() => {
135	                by_base
136	                    .entry(commit.as_str().to_owned())
137	                    .or_default()
138	                    .push((pkg, directories));
139	            }
140	            Some(commit) => {
141	                let files = list_files(git, &diff_command(commit.as_str()), &directories, &excludes)?;
142	                result.insert(pkg.id.clone(), files.into_iter().collect());
143	            }
144	            None => {
145	                let files = list_files(git, &["ls-files", "-z"], &directories, &excludes)?;
146	                result.insert(pkg.id.clone(), files.into_iter().collect());
147	            }
148	        }
149	    }
150	    for (commit, group) in &by_base {
151	        let specs: Vec<Vec<PathBuf>> = group.iter().map(|(_, directories)| directories.clone()).collect();
152	        let all: Vec<PathBuf> = specs.iter().flatten().cloned().collect();
153	        let listed = list_in_chunks(git, &diff_command(commit), &all, &excludes, budget)?;
154	        // A file belongs to every package whose directory contains it, as it did when each package had its own diff.
155	        let index = SpecIndex::new(&specs);
156	        let mut owned: Vec<BTreeSet<PathBuf>> = vec![BTreeSet::new(); group.len()];
157	        for path in listed {
158	            index.owners_of(&path, |package| {
159	                owned[package].insert(path.clone());
160	            });
161	        }
162	        for ((pkg, _), files) in group.iter().zip(owned) {
163	            result.insert(pkg.id.clone(), files.into_iter().collect());
164	        }
165	    }
166	    Ok(result)
167	}
