173	/// `list_files` over `directories`, split so no command carries more than `budget` bytes of pathspec.
174	fn list_in_chunks(
175	    git: &GitAccess<'_>,
176	    command: &[&str],
177	    directories: &[PathBuf],
178	    excludes: &[String],
179	    budget: usize,
180	) -> Result<BTreeSet<PathBuf>, GraphError> {
181	    let fixed: usize = excludes.iter().map(|exclude| exclude.len() + 1).sum();
182	    let mut listed = BTreeSet::new();
183	    let mut start = 0;
184	    while start < directories.len() {
185	        let mut end = start;
186	        let mut bytes = fixed;
187	        while end < directories.len() && (end == start || bytes + directories[end].as_os_str().len() < budget) {
188	            bytes += directories[end].as_os_str().len() + 1;
189	            end += 1;
190	        }
191	        listed.extend(list_files(git, command, &directories[start..end], excludes)?);
192	        start = end;
193	    }
194	    Ok(listed)
195	}
