197	/// The paths `git <command> -- <directories> <excludes>` prints, which is NUL-separated.
198	fn list_files(
199	    git: &GitAccess<'_>,
200	    command: &[&str],
201	    directories: &[PathBuf],
202	    excludes: &[String],
203	) -> Result<BTreeSet<PathBuf>, GraphError> {
204	    let mut args: Vec<String> = command.iter().map(|arg| (*arg).to_owned()).collect();
205	    args.push("--".to_owned());
206	    args.extend(directories.iter().map(|d| d.to_string_lossy().into_owned()));
207	    args.extend(excludes.iter().cloned());
208	    let arg_refs: Vec<&str> = args.iter().map(String::as_str).collect();
209	    let output = git.runner().run("git", &arg_refs, git.root()).map_err(VcsError::from)?;
210	    if !output.success() {
211	        return Err(VcsError::Git(format!(
212	            "`git {}` failed in `{}`: {}",
213	            args[0],
214	            git.root().display(),
215	            output.redacted_stderr()
216	        ))
217	        .into());
218	    }
219	    Ok(output
220	        .stdout
221	        .split('\0')
222	        .map(|path| path.trim_start_matches('\n'))
223	        .filter(|path| !path.is_empty())
224	        .map(PathBuf::from)
225	        .collect())
226	}
