228	fn exclude_pathspec(pattern: &str) -> String {
229	    match pattern.strip_suffix('/') {
230	        Some(directory) => format!(":(exclude,glob)**/{directory}/**"),
231	        None => format!(":(exclude,glob)**/{pattern}"),
232	    }
233	}
