235	/// Whether `id` is released with `covered`: it is covered itself, or a member of its fixed or linked group is, since a
236	/// group moves together.
237	pub fn is_covered(id: &PackageId, covered: &BTreeSet<PackageId>, groups: &GroupTable) -> bool {
238	    covered.contains(id)
239	        || [(&groups.fixed_of, &groups.fixed), (&groups.linked_of, &groups.linked)]
240	            .into_iter()
241	            .filter_map(|(of, defs)| of.get(id).and_then(|name| defs.get(name)))
242	            .any(|group| group.package_members().any(|member| covered.contains(member)))
243	}
