245	/// Packages with a changed source file that nothing releases: not [covered](is_covered).
246	pub fn uncovered_changes(
247	    changed: &BTreeMap<PackageId, Vec<PathBuf>>,
248	    covered: &BTreeSet<PackageId>,
249	    groups: &GroupTable,
250	) -> Vec<PackageId> {
251	    changed
252	        .iter()
253	        .filter(|(id, files)| !files.is_empty() && !is_covered(id, covered, groups))
254	        .map(|(id, _)| id.clone())
255	        .collect()
256	}
