258	/// The changed source files of the packages in `packages` that nothing releases, without a git process per package.
259	/// Covered packages are skipped outright, whether or not they changed; the rest are told apart by tree id in a fixed
260	/// number of processes, and only a package that really changed pays for its own file listing.
261	pub fn changed_source_files_of_uncovered(
262	    packages: &[&Package],
263	    tags: &TagIndex,
264	    git: &GitAccess<'_>,
265	    covered: &BTreeSet<PackageId>,
266	    groups: &GroupTable,
267	    ignore: &[&str],
268	) -> Result<BTreeMap<PackageId, Vec<PathBuf>>, GraphError> {
269	    let candidates: Vec<&Package> = packages
270	        .iter()
271	        .copied()
272	        .filter(|package| !is_covered(&package.id, covered, groups))
273	        .collect();
274	    let touched = changed_since_last_tag(&candidates, tags, git)?;
275	    let changed: Vec<&Package> = candidates
276	        .into_iter()
277	        .filter(|package| touched.get(&package.id).copied().unwrap_or(false))
278	        .collect();
279	    changed_source_files_since_last_tag(&changed, tags, git, ignore)
280	}
