282	/// Which packages a path belongs to: those with a spec that is an ancestor directory of it, and those with the `.`
283	/// spec, which every path falls under.
284	struct SpecIndex<'a> {
285	    by_directory: std::collections::HashMap<&'a Path, Vec<usize>>,
286	    everywhere: Vec<usize>,
287	}
288	
289	impl<'a> SpecIndex<'a> {
290	    fn new(specs: &'a [Vec<PathBuf>]) -> Self {
291	        let mut by_directory: std::collections::HashMap<&Path, Vec<usize>> = std::collections::HashMap::new();
292	        let mut everywhere = Vec::new();
293	        for (package, package_specs) in specs.iter().enumerate() {
294	            for spec in package_specs {
295	                if spec.as_path() == Path::new(".") {
296	                    everywhere.push(package);
297	                } else {
298	                    by_directory.entry(spec.as_path()).or_default().push(package);
299	                }
300	            }
301	        }
302	        SpecIndex {
303	            by_directory,
304	            everywhere,
305	        }
306	    }
307	
308	    fn owners_of(&self, path: &Path, mut found: impl FnMut(usize)) {
309	        for &package in &self.everywhere {
310	            found(package);
311	        }
312	        for directory in path.ancestors() {
313	            for &package in self.by_directory.get(directory).into_iter().flatten() {
314	                found(package);
315	            }
316	        }
317	    }
318	}
