844	    /// The old behaviour: one diff (or `ls-files`, untagged) per package.
845	    fn per_package_reference(root: &Path, pkgs: &[Package]) -> BTreeMap<PackageId, Vec<PathBuf>> {
846	        let excludes: Vec<String> = DEFAULT_IGNORED_PATHS.iter().map(|p| exclude_pathspec(p)).collect();
847	        pkgs.iter()
848	            .map(|pkg| {
849	                let tag = format!("{}@1.0.0", pkg.id);
850	                let tagged = run_git_ok(root, &["rev-parse", "-q", "--verify", &format!("{tag}^{{commit}}")]);
851	                let mut args: Vec<String> = match &tagged {
852	                    Some(commit) => [
853	                        "diff",
854	                        "--no-renames",
855	                        "--relative",
856	                        "--name-only",
857	                        "-z",
858	                        commit.trim(),
859	                        "--",
860	                    ]
861	                    .map(String::from)
862	                    .to_vec(),
863	                    None => ["ls-files", "-z", "--"].map(String::from).to_vec(),
864	                };
865	                args.extend(package_paths(pkg).iter().map(|d| d.to_string_lossy().into_owned()));
866	                args.extend(excludes.iter().cloned());
867	                let refs: Vec<&str> = args.iter().map(String::as_str).collect();
868	                let output = GitRunner.run("git", &refs, root).unwrap();
869	                let files: BTreeSet<PathBuf> = output
870	                    .stdout
871	                    .split('\0')
872	                    .filter(|path| !path.is_empty())
873	                    .map(PathBuf::from)
874	                    .collect();
875	                (pkg.id.clone(), files.into_iter().collect())
876	            })
877	            .collect()
878	    }
